import { eventBus } from '../../orchestra/event-bus.js';
import { createMonitorAdapter } from '../../orchestra/monitor-adapter.js';
import { StatusRenderer } from '../helpers/status-renderer.js';
import { hideCursor, showCursor, clearScreen } from '../helpers/ansi.js';

export function registerStatus(program: Command): void {
  program.command('status')
    .option('--watch', 'Poll-based refresh every 5s (legacy)')
    .option('-f, --follow', 'Follow mode: snapshot + live event tail')
    .action(async (opts) => {
      if (opts.follow) {
        const adapter = createMonitorAdapter(loadConfig());
        const renderer = new StatusRenderer(adapter);
        process.stdout.write(hideCursor() + clearScreen());
        const initial = await renderer.snapshot();
        process.stdout.write(initial);
        const unsubscribe = eventBus.subscribe(currentSprintId, undefined, async () => {
          const next = await renderer.snapshot();
          renderer.redraw(next);
        });
        process.on('SIGINT', () => {
          unsubscribe();
          process.stdout.write(showCursor() + '\n');
          process.exit(0);
        });
      } else {
        // existing snapshot/watch behavior
      }
    });
}
```

